// Generated by tools/build_appellations.py from the Vitis Mundi atlas. Do not edit by hand.
APX.hr = {"country":{"name":"Croatia","tagline":"Zinfandel's homeland, cliff-hung Plavac Mali, island whites with Greek roots, and the Graševina plains of Slavonia.","classification":"Croatian wine law nests regions (*regije*), subregions (*podregije*), vineyard areas (*vinogorja*) and single positions (*položaji*). Under the EU system 18 names are PDOs (*zaštićena oznaka izvornosti*, ZOI): the regions Istočna kontinentalna Hrvatska, Zapadna kontinentalna Hrvatska and Primorska Hrvatska; the subregions Hrvatsko Podunavlje, Slavonija, Moslavina, Prigorje-Bilogora, Plešivica, Pokuplje, Zagorje-Međimurje, Hrvatska Istra, Hrvatsko primorje, Sjeverna Dalmacija, Srednja i Južna Dalmacija and Dalmatinska zagora; and the site appellations Dingač, Ponikve and Muškat momjanski. Labels still use the traditional quality terms *kvalitetno vino* (quality wine) and *vrhunsko vino* (premium wine), and Prädikat-style sweet categories (*kasna berba*, *izborna berba*, *izborna berba bobica*, *izborna berba prosušenih bobica*, *ledeno vino*). Prošek, the Dalmatian dried-grape dessert wine, is a traditional term whose EU protection Croatia sought from 2021, against Italian objections that it is too close to Prosecco."},"regions":[{"name":"Istria and Kvarner","slug":"istria-and-kvarner","tagline":"Heart-shaped Istria, its hill towns and red earth: Malvazija, Teran and Momjan Muscat.","ids":["hr-hrvatska-istra","hr-hrvatsko-primorje","hr-muskat-momjanski"]},{"name":"Dalmatia","slug":"dalmatia","tagline":"Karst cliffs, island fields walled by Greeks and the wild-hearted Plavac Mali: the Adriatic's most dramatic vineyards.","ids":["hr-dalmatinska-zagora","hr-dingac","hr-ponikve","hr-primorska-hrvatska","hr-sjeverna-dalmacija","hr-srednja-i-juzna-dalmacija"]},{"name":"Slavonia and Croatian Danube","slug":"slavonia-and-croatian-danube","tagline":"The Golden Valley of Graševina, Cistercian cellars and the loess terraces of the Danube at Ilok.","ids":["hr-hrvatsko-podunavlje","hr-istocna-kontinentalna-hrvatska","hr-slavonija"]},{"name":"Croatian Uplands","slug":"croatian-uplands","tagline":"The hills around Zagreb: sparkling Plešivica, aromatic Međimurje Pušipel and Moslavina's Škrlet.","ids":["hr-moslavina","hr-plesivica","hr-pokuplje","hr-prigorje-bilogora","hr-zagorje-medimurje","hr-zapadna-kontinentalna-hrvatska"]}],"items":{"hr-dalmatinska-zagora":{"name":"Dalmatinska zagora","cat":"ZOI","region":"Dalmatia","created":"EU PDO 2013","styles":["white","red"],"grapes":"Kujundžuša, Trnjak, Debit, Maraština, Plavac Mali","summary":"Dalmatinska zagora is the karst hinterland behind the coast, from Knin and Drniš to Sinj, Imotski and Vrgorac. Its higher, drier and cooler plateaus give fresher wines than the coast; Kujundžuša (Imotski) and Trnjak are the local grapes, and Debit grows around Drniš.","rslug":"dalmatia"},"hr-dingac":{"name":"Dingač","cat":"ZOI","region":"Dalmatia","subregion":"Srednja i Južna Dalmacija","created":"1961 (Yugoslav protection); EU PDO 2013","area_ha":78,"styles":["red"],"grapes":"Plavac Mali","summary":"Dingač is Croatia's most famous red wine and its first protected wine region (1961): a steep strip of south-west-facing slopes on the Pelješac peninsula above the sea, between Trstenik and Borak, worked from the village of Potomje on the other side of the ridge. Only Plavac Mali is permitted, with a maximum of 8 t/ha. The slopes reach 45 degrees on crumbling dolomitic limestone with almost no topsoil, and the vines get sun from above, light reflected from the sea and heat radiated by the stones, so the grapes shrivel and concentrate. The wines are dark, tannic, often 15% alcohol or more, with dried fig, carob, black cherry, tobacco and herb notes. Until 1975 the grapes went over the ridge by donkey; the growers' cooperative then financed a 400 m tunnel from Potomje. The protected area covers about 758 ha, of which about 78 ha are planted.","terroir":"Karst dolomite and limestone scree, slopes up to 45 degrees, 0 to 300 m above the sea, extreme sun and heat; dry-farmed bush vines.","producers":["Matuško","Saints Hills","Bura-Mrgudić","Madirazza","Skaramuča","Vinarija Dingač (Potomje)","Kiridžija","Miloš"],"nerd_note":"Plavac Mali is a cross of Tribidrag (Zinfandel) and Dobričić, an old variety from the island of Šolta, so every bottle of Dingač is Zinfandel's grandchild in a sense.","rslug":"dalmatia"},"hr-hrvatska-istra":{"name":"Hrvatska Istra","cat":"ZOI","region":"Istria and Kvarner","created":"EU PDO 2013","styles":["white","red","orange","sweet","sparkling"],"grapes":"Malvazija Istarska, Teran, Merlot, Cabernet Sauvignon, Refošk, Muscat","summary":"Hrvatska Istra is the subregional PDO for Croatian Istria, 41 municipalities from Umag and Buje to Pula and Labin. It is Croatia's most dynamic wine region: Malvazija Istarska makes up about half the plantings, followed by Teran, Merlot, Cabernet, Refošk and Muscat. The west coast's red terra rossa gives riper, rounder wines; the grey and white marls of the interior around Motovun, Buje and Momjan give tighter whites. Producers range from the large Agrolaguna to family estates such as Kozlović, Matošević, Roxanich, Clai, Coronica, Trapan, Kabola, Benvenuti, Cattunar and Arman.","producers":["Kozlović","Matošević","Roxanich","Clai","Coronica","Trapan","Kabola","Benvenuti","Cattunar","Arman"],"nerd_note":"Croatian producers can label Teran only with 'Hrvatska Istra' alongside it, under a 2017 EU derogation that Slovenia, which holds the Teran PDO, contested.","rslug":"istria-and-kvarner"},"hr-hrvatsko-podunavlje":{"name":"Hrvatsko Podunavlje","cat":"ZOI","region":"Slavonia and Croatian Danube","created":"EU PDO 2013","styles":["white","sweet","red"],"grapes":"Graševina, Traminac, Rhine Riesling, Chardonnay, Frankovka, Cabernet Sauvignon","summary":"Croatian Danube covers the loess ridges along the Danube in Baranja (Zmajevac, Kneževi Vinogradi), Erdut and Srijem (Ilok). Ilok's Traminac and Graševina, from the large Iločki podrumi, are the best-known wines; Erdutski vinogradi and Belje are other major estates.","producers":["Iločki podrumi","Erdutski vinogradi","Belje","Josić","Buhač"],"rslug":"slavonia-and-croatian-danube"},"hr-hrvatsko-primorje":{"name":"Hrvatsko primorje","cat":"ZOI","region":"Istria and Kvarner","created":"EU PDO 2013","styles":["white","red"],"grapes":"Žlahtina, Gegić, Sansigot, Trojišćina, Malvazija","summary":"Hrvatsko primorje covers the Kvarner gulf and its islands (Krk, Cres, Lošinj, Rab, Pag) and the coast from Rijeka to Karlobag. Its best-known wine is Vrbnička Žlahtina from Vrbnik on Krk, a light, fresh, floral white from the native Žlahtina; Pag's Gegić is another island specialty.","rslug":"istria-and-kvarner"},"hr-istocna-kontinentalna-hrvatska":{"name":"Istočna kontinentalna Hrvatska","cat":"ZOI","region":"Slavonia and Croatian Danube","created":"EU PDO 2013","styles":["white","red"],"grapes":"Graševina and other permitted continental varieties","summary":"The regional umbrella PDO for eastern continental Croatia, covering Slavonija and Hrvatsko Podunavlje (133 municipalities), used for wines blended across the two subregions, typically larger-volume Graševina from producers who buy fruit from both Slavonia and the Danube.","rslug":"slavonia-and-croatian-danube"},"hr-moslavina":{"name":"Moslavina","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["white"],"grapes":"Škrlet, Graševina, Chardonnay, Sauvignon","summary":"Moslavina is a small hill range south-east of Zagreb around Kutina and Popovača. It is the home of Škrlet, a native white with light body, citrus and herbal notes, rescued from near-extinction and now the subregion's calling card.","producers":["Mikša","Florijanović","Voštinić-Klasnić"],"rslug":"croatian-uplands"},"hr-muskat-momjanski":{"name":"Muškat momjanski","cat":"ZOI","region":"Istria and Kvarner","subregion":"Hrvatska Istra","created":"EU PDO 2021","styles":["sweet","white"],"grapes":"Muscat Blanc à Petits Grains (Momjan muscat)","summary":"Muškat momjanski is a PDO (August 2021) for wines from Muscat Blanc à Petits Grains grown around the hilltop village of Momjan near Buje in north-west Istria. Momjan's muscat was famous in the Habsburg period; today it is made dry, off-dry and as a sweet late-harvest wine with orange-blossom and honey notes. Kozlović and Prelac are among the producers.","producers":["Kozlović","Prelac"],"rslug":"istria-and-kvarner"},"hr-plesivica":{"name":"Plešivica","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["sparkling","white","red"],"grapes":"Chardonnay, Pinot Noir, Graševina, Rhine Riesling, Sauvignon, Portugizac","summary":"Plešivica, a low range of hills west of Zagreb around Jastrebarsko and Samobor, is Croatia's sparkling-wine capital and one of its most forward-thinking areas. Tomac, Korak, Režek, Jagunić and Šember make traditional-method sparkling and still wines from Chardonnay, Pinot Noir, Riesling, Graševina, Sauvignon and Portugizac; Tomac also ferments in buried amphorae.","producers":["Tomac","Korak","Režek","Jagunić","Šember","Kurtalj"],"rslug":"croatian-uplands"},"hr-pokuplje":{"name":"Pokuplje","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["white"],"grapes":"Graševina, Kraljevina, Chardonnay, Portugizac","summary":"Pokuplje follows the Kupa river south-west of Zagreb around Karlovac and Ozalj; a small, cool subregion of light whites (Graševina, Kraljevina, Chardonnay) and some Portugizac. Its scattered hillside plots are mostly family vineyards for home consumption, with only a few commercial bottlers.","rslug":"croatian-uplands"},"hr-ponikve":{"name":"Ponikve","cat":"ZOI","region":"Dalmatia","subregion":"Srednja i Južna Dalmacija","created":"EU PDO 2021","styles":["red","white","sweet"],"grapes":"Plavac Mali, Pošip, Maraština","summary":"Ponikve, registered in February 2021 as Croatia's 17th wine PDO, is a small plateau and hamlet near Ston at the neck of the Pelješac peninsula. The PDO covers wines from Plavac Mali, Pošip and Maraština, including a style made from raisined grapes, and was created to give the locality's name visibility on labels. Ponikve's karst fields sit higher and cooler than the south-facing Dingač slopes.","rslug":"dalmatia"},"hr-prigorje-bilogora":{"name":"Prigorje-Bilogora","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["white"],"grapes":"Kraljevina, Graševina, Pinot Gris, Chardonnay","summary":"Prigorje-Bilogora takes in the slopes north and east of Zagreb (Zelina, Križevci, Koprivnica, Bjelovar). It makes light whites, notably Kraljevina around Sveti Ivan Zelina, plus Graševina and Pinot Gris. Zelina's Kraljevina, a pink-skinned, low-alcohol local grape, is the classic wine of Zagreb's taverns.","rslug":"croatian-uplands"},"hr-primorska-hrvatska":{"name":"Primorska Hrvatska","cat":"ZOI","region":"Dalmatia","created":"EU PDO 2013","styles":["white","red","rose","sweet"],"grapes":"All permitted coastal varieties","summary":"Primorska Hrvatska is the regional umbrella PDO for all of coastal Croatia (Istria, Kvarner and Dalmatia), about 180 municipalities, used for wines blended across subregions. A producer who buys Plavac Mali from Pelješac and Babić from Primošten for one wine, for instance, labels it Primorska Hrvatska; most quality wines name their subregion instead.","rslug":"dalmatia"},"hr-sjeverna-dalmacija":{"name":"Sjeverna Dalmacija","cat":"ZOI","region":"Dalmatia","created":"EU PDO 2013","styles":["red","white","rose"],"grapes":"Babić, Plavac Mali, Lasina, Debit, Maraština","summary":"Northern Dalmatia runs from Zadar to Primošten and Rogoznica, with the islands of Pašman, Ugljan and the Kornati. Its signature is Babić, a dark, firm red grown around Primošten and Šibenik in tiny vineyards hacked out of bare limestone and protected by dry-stone walls; Debit and Maraština are the whites.","producers":["Gracin","Bibich","Badel 1862 (Benkovac)"],"rslug":"dalmatia"},"hr-slavonija":{"name":"Slavonija","cat":"ZOI","region":"Slavonia and Croatian Danube","created":"EU PDO 2013","styles":["white","sweet","red"],"grapes":"Graševina, Traminac, Chardonnay, Pinot Blanc, Sauvignon, Frankovka","summary":"Slavonija is the subregion of the hills ringing the Požega basin and the northern slopes toward the Drava: Kutjevo, Orahovica, Feričanci, Đakovo, Slavonski Brod, Daruvar and Pakrac. Its 'Golden Valley' around Kutjevo is Croatia's Graševina heartland, with wines from crisp and appley to oak-aged and botrytised; Traminac, Pinot Blanc, Chardonnay, Sauvignon and Frankovka also do well. Cistercians built Kutjevo's first cellar in 1232.","terroir":"Loess, clay and marl on south-facing slopes of the Papuk and Krndija hills at 150 to 350 m; continental climate.","producers":["Kutjevo","Krauthaker","Enjingi","Galić","Feravino","Josić","Mihalj","Adžić"],"rslug":"slavonia-and-croatian-danube"},"hr-srednja-i-juzna-dalmacija":{"name":"Srednja i Južna Dalmacija","cat":"ZOI","region":"Dalmatia","created":"EU PDO 2013","styles":["red","white","rose","sweet"],"grapes":"Plavac Mali, Tribidrag, Pošip, Grk, Bogdanuša, Vugava, Malvasija Dubrovačka, Maraština","summary":"Central and Southern Dalmatia covers the coast from Trogir and Split to Dubrovnik and Konavle plus the islands of Brač, Hvar, Vis, Korčula, Šolta, Lastovo and Mljet, and Pelješac. It holds most of Croatia's great coastal wines: Plavac Mali from Pelješac (Postup, Trstenik), Hvar (Sveta Nedjelja, Ivan Dolac) and Brač; Pošip and Grk from Korčula; Bogdanuša from Hvar; Vugava from Vis; Crljenak Kaštelanski from Kaštela; and Malvasija Dubrovačka from Konavle.","producers":["Grgić","Saints Hills","Korta Katarina","Stina","Tomić","Zlatan Otok","Plenković","Krajančić","Toreta","Bire","Lumbarda","Karaman"],"contains":["Postup"],"rslug":"dalmatia"},"hr-zagorje-medimurje":{"name":"Zagorje, Međimurje","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["white","sweet","sparkling"],"grapes":"Pušipel (Furmint), Sauvignon, Rhine Riesling, Graševina, Traminac, Muscat","summary":"Zagorje-Međimurje covers the hills of Hrvatsko Zagorje north of Zagreb and Međimurje between the Mura and Drava, against the Slovenian and Hungarian borders. Međimurje's steep Štrigova hills make taut, aromatic Sauvignon, Riesling and Pušipel (local Furmint), and some excellent late-harvest wines.","producers":["Bolfan","Štampar","Cmrečnjak","Jakopić","Lovrec"],"rslug":"croatian-uplands"},"hr-zapadna-kontinentalna-hrvatska":{"name":"Zapadna kontinentalna Hrvatska","cat":"ZOI","region":"Croatian Uplands","created":"EU PDO 2013","styles":["white","red","sparkling"],"grapes":"All permitted continental varieties","summary":"The regional umbrella PDO for western continental Croatia, covering the five upland subregions (about 200 municipalities): Plešivica, Zagorje-Međimurje, Prigorje-Bilogora, Moslavina and Pokuplje. It is used for wines that blend fruit across those hills or do not qualify for a subregion name.","rslug":"croatian-uplands"}}};
